import { appUrl } from './paths.mjs';
import {ROUTES,DEFAULTS,evaluate,money,dateLabel} from './model.mjs';
import {scenarioImpact} from './scenario-impact.mjs';
import {routeMap} from './route-map.mjs';
const names={suez:'Suez Canal',cape:'Cape of Good Hope',rail:'Middle Corridor'};
const selectedRoute=id=>ROUTES.find(r=>r.id===id);
const status=(r,icon)=>`<span class="case-status ${r.feasible?'within':'outside'}">${icon(r.feasible?'check':'alert',14)}${r.feasible?'Within limits':r.failures[0]}</span>`;
function comparison(icon){
 return `<div class="case-comparison"><div class="case-comparison-head"><span>Same shipment. Same assumptions.</span><span>Budget €22,000 · Due 14 Dec</span></div><div class="case-comparison-table"><div class="case-comparison-labels"><span>Corridor</span><span>Logistics cost</span><span>Estimated arrival</span><span>Transport emissions</span><span>Planning status</span></div>${['cape','suez','rail'].map(id=>{const r=evaluate(selectedRoute(id),DEFAULTS);return `<div class="case-comparison-column ${id==='suez'?'is-featured':''}"><span>${names[id]}${id==='cape'?'<small>Starting plan</small>':id==='suez'?'<small>Best fit · Balanced</small>':'<small>Fastest eligible</small>'}</span><strong>${money(r.cost)}</strong><span>${dateLabel(r.arrival)}<small>${r.buffer<0?`${-r.buffer}d late`:`${r.buffer}d to spare`}</small></span><span>${r.co2.toFixed(1)} t CO₂e<small>±${r.uncertainty}% estimate range</small></span>${status(r,icon)}</div>`}).join('')}</div><div class="case-comparison-takeaway"><span>${icon('compare',22)}</span><p><strong>€1,540 more. Nine days earlier.</strong><span>Suez meets the limits; the cheaper Cape route misses the deadline.</span></p></div></div>`;
}
function stress(delay,icon){
 const impact=scenarioImpact({...DEFAULTS,delay});
 return `<div class="case-stress"><div class="case-stress-controls"><div><span class="case-kicker">SUEZ CANAL / PORT DELAY</span><h3>Change one assumption.</h3><p>Fuel and planning limits stay fixed.</p></div><div class="case-toggle" aria-label="Case study port delay"><button data-action="case-delay" data-value="0" aria-pressed="${delay===0}">Base case</button><button data-action="case-delay" data-value="7" aria-pressed="${delay===7}">+7 days</button></div></div><div class="case-impact-grid"><article><span>Estimated arrival</span><strong>${dateLabel(impact.after.arrival)}</strong><small>${delay?`${impact.daysChange} days later`:'At base assumptions'}</small></article><article><span>Deadline buffer</span><strong class="${impact.after.buffer<0?'caution':'good'}">${impact.after.buffer<0?'−':''}${Math.abs(impact.after.buffer)} <i>days</i></strong><small>${impact.after.buffer<0?'Past the delivery deadline':'Before the delivery deadline'}</small></article><article><span>Routes within limits</span><strong>${impact.eligibleAfter}<i> / 6</i></strong><small>${delay?'Middle Corridor remains eligible':'Suez and Middle Corridor'}</small></article></div><div class="case-stress-verdict ${delay?'is-delayed':''}">${icon(delay?'alert':'check',20)}<div><strong>${delay?'A valid plan can stop being valid.':'Suez fits the current constraints.'}</strong><p>${delay?'Suez now arrives on 17 Dec. Inspecting the Middle Corridor offers an eligible alternative.':'Delivery, budget and emissions all fit. Add a delay to see the recommendation change.'}</p></div><button class="button outline" data-action="try-delay-scenario">Try in workspace ${icon('arrow',15)}</button></div></div>`;
}
function decision(icon){
 return `<div class="case-record"><div class="case-record-heading"><div><span class="case-kicker">EXAMPLE DECISION RECORD</span><h3>Suez · December delivery</h3></div><span>${icon('bookmark',17)} Saved snapshot</span></div><div class="case-record-grid"><div><span>Corridor</span><strong>Suez Canal</strong></div><div><span>Arrival</span><strong>10 Dec</strong></div><div><span>Logistics cost</span><strong>€18,420</strong></div><div><span>Assumptions</span><strong>Fuel 0% · Delay 0d</strong></div></div><blockquote><span>RATIONALE</span><p>Arrives before the deadline and stays inside the €22,000 budget. The Cape alternative saves €1,540 but arrives five days late.</p></blockquote><div class="case-record-foot">${icon('lock',15)} The snapshot keeps its original assumptions when the workspace changes.<span>Illustrative record · No booking</span></div></div>`;
}
export function caseStudyView(state,icon,mark){
 const route=evaluate(selectedRoute(state.route),DEFAULTS),ref=state.route==='cape'?'suez':'cape';
 return `<div class="case-editorial"><header class="case-masthead"><a href="${appUrl()}" data-action="nav" data-view="planner">${mark}<span>ValencePort</span></a><span>Product design / Case study</span><button class="text-button" data-action="nav" data-view="planner">Open workspace ${icon('arrow',16)}</button></header><section class="case-opening"><div><span class="case-kicker">FREIGHT SCENARIO PLANNING</span><h1>A clearer route<br>through the<br><em>trade-offs.</em></h1></div><div class="case-opening-note"><p>Six corridors. Three constraints.<br>One decision to stand behind.</p><p>A working tool for comparing freight routes, testing assumptions and keeping the reason behind a plan.</p><button class="button primary" data-action="nav" data-view="planner">Explore the prototype ${icon('arrow',17)}</button><dl><div><dt>DESIGNER</dt><dd>Robert Vaganian</dd></div><div><dt>CONTRIBUTION</dt><dd>Product design & prototyping</dd></div><div><dt>FORMAT</dt><dd>Self-initiated desktop concept</dd></div></dl></div></section><figure class="case-atlas"><header><span>${icon('mixed',18)} <strong>Shanghai → Rotterdam</strong><small>SHP-2026-0842 · Industrial components</small></span><span>Budget €22,000 <i>·</i> Due 14 Dec <i>·</i> CO₂e ≤ 40 t</span></header><div class="case-atlas-workspace"><div class="case-map">${routeMap(route,ref,{interactive:false})}</div><aside><span class="case-kicker">SELECTED CORRIDOR</span><h2>${names[state.route]}</h2>${status(route,icon)}<dl><div><dt>Logistics cost</dt><dd>${money(route.cost)}</dd></div><div><dt>Estimated arrival</dt><dd>${dateLabel(route.arrival)}</dd></div><div><dt>Transit</dt><dd>${route.days}<small> days</small></dd></div></dl><p>${state.route==='cape'?'The lowest quote misses the delivery deadline by five days.':state.route==='rail'?'A faster eligible alternative, with more handovers and a wider emissions range.':'€1,540 more than Cape. Nine days earlier, within all three limits.'}</p></aside></div><figcaption><div class="case-route-switch" role="group" aria-label="Explore case study corridors">${['suez','cape','rail'].map(id=>`<button data-action="case-route" data-value="${id}" aria-pressed="${state.route===id}">${icon(id==='rail'?'train':'ship',16)}${names[id]}</button>`).join('')}</div><span>Select a corridor · Actual prototype geometry</span></figcaption></figure><nav class="case-section-nav" aria-label="Case study sections"><a href="#case-problem">The problem</a><a href="#case-decisions">The decisions</a><a href="#case-language">Visual language</a><a href="#case-scope">Scope & validation</a></nav><section id="case-problem" class="case-story-section"><div class="case-section-label"><b>01</b><span>THE PROBLEM</span></div><div class="case-story-copy"><h2>A lower quote<br>can hide a worse plan.</h2><div class="case-problem-columns"><p>A freight planner needs an option that fits delivery, budget and emissions constraints. Looking at price first can make a late route look like the winner.</p><p>ValencePort keeps the same shipment and assumptions behind every option. It separates eligibility from preference, then makes the compromise visible.</p></div></div></section><section id="case-decisions" class="case-decisions-section"><div class="case-story-section"><div class="case-section-label"><b>02</b><span>THE DECISIONS</span></div><div class="case-story-copy"><h2>Compare. Question.<br>Keep the reason.</h2><p>Three connected decisions shape the workspace. Explore each one below; the examples use the same calculation model as the prototype.</p></div></div><div class="case-explorer"><nav aria-label="Explore design decisions">${[['compare','01','Make the trade-off visible'],['stress','02','Test the assumptions'],['record','03','Preserve the rationale']].map(([id,n,label])=>`<button data-action="case-scene" data-value="${id}" aria-pressed="${state.scene===id}"><span>${n}</span>${label}${icon('arrow',15)}</button>`).join('')}</nav><div class="case-explorer-scene">${state.scene==='compare'?comparison(icon):state.scene==='stress'?stress(state.delay,icon):decision(icon)}</div><p class="case-explorer-caption">${state.scene==='compare'?'Eligibility comes first. Preferences then rank the routes that meet every limit.':state.scene==='stress'?'Same-route impact stays separate from comparison against a pinned baseline.':'Save the decision context, rather than a number that loses its meaning later.'}</p></div></section><section class="case-story-section case-interaction-story"><div class="case-section-label"><b>03</b><span>INTERACTION</span></div><div class="case-story-copy"><h2>Room to explore.<br>Detail when it matters.</h2><div class="case-interaction-list"><article><span>${icon('expand',22)}</span><div><h3>The map earns its space.</h3><p>Fold away navigation or expand the map. Pointer-centred zoom preserves place; named controls keep overlapping services selectable. The inspector holds the selected metrics, without repeating them below the map.</p></div></article><article><span>${icon('route',22)}</span><div><h3>Motion explains a change.</h3><p>A continuous reveal traces a selected corridor to its endpoint at any zoom. Hover or keyboard focus highlights an alternative. Route types and observation gaps retain their own line styles.</p></div></article><article><span>${icon('play',22)}</span><div><h3>Show the action, then let people try.</h3><p>The five-step tour shows a clear before, action and result. Each example stops on its result, with manual frames, pause and replay. It teaches selection, comparison and stress tests without changing the workspace.</p><button class="text-button" data-action="guide">Watch the quick tour ${icon('arrow',15)}</button></div></article></div></div></section><section id="case-language" class="case-story-section"><div class="case-section-label"><b>04</b><span>VISUAL LANGUAGE</span></div><div class="case-story-copy"><h2>Industrial clarity.<br>A human rhythm.</h2><p>Plex keeps labels, currencies and dense comparisons legible. Archivo gives the headings a compact, transport-inspired character. A warm stone palette separates the workspace from the map; restrained status tones carry meaning without flooding the rows.</p><div class="case-type-specimen"><article><span class="case-kicker">ARCHIVO / HEADINGS</span><strong>Clear routes.<br>Considered choices.</strong></article><article><span class="case-kicker">IBM PLEX SANS / INTERFACE</span><strong>€18,420 <small>31 days</small></strong><p>Supplier · Handling · Contingency<br>Shanghai → Rotterdam</p></article></div><div class="case-palette"><span><i style="background:var(--green)"></i>Petroleum / Action</span><span><i style="background:var(--green-bg);border:1px solid var(--green-text)"></i>Sage / Within limits</span><span><i style="background:var(--warning-bg);border:1px solid var(--warning)"></i>Berry / Outside limits</span><span><i style="background:var(--bg);border:1px solid var(--line-strong)"></i>Ivory / Workspace</span></div></div></section><section id="case-scope" class="case-story-section case-boundaries"><div class="case-section-label"><b>05</b><span>SCOPE & VALIDATION</span></div><div class="case-story-copy"><h2>A working concept.<br>Honest boundaries.</h2><div class="case-scope-grid"><div><h3>What works</h3><p>Six-route comparison, constraint ranking, stress tests, journey inspection, saved snapshots and exports. The light and dark themes share the same semantic colors and readable type hierarchy.</p></div><div><h3>What the data means</h3><p>Prices, transit and emissions are illustrative. Sea, rail and road geometry uses documented networks. Air links are indicative; the optional dated flight example retains observation gaps. No booking or operational clearance is implied.</p></div><div><h3>What was checked</h3><p>Calculations, ranking, saved records, route geometry and continuity are covered by automated checks. Interface review focuses on responsive layout, keyboard controls, reduced motion, contrast and complete route reveals.</p></div><div><h3>What comes next</h3><p>The concept has not been tested with logistics professionals. A research round should test how planners explain ineligibility, uncertainty ranges and the meaning of a saved scenario. No measured business impact is claimed.</p></div></div><button class="text-button" data-action="methodology">Read data & methodology ${icon('external',15)}</button></div></section><footer class="case-closing"><div>${mark}<span>ValencePort</span></div><h2>Make a plan.<br>Know the compromise.</h2><button class="button primary" data-action="nav" data-view="planner">Open the workspace ${icon('arrow',17)}</button><span>Designed by Robert Vaganian · Self-initiated concept</span></footer></div>`;
}
